(function(){"use strict";function init(){const phoneInput=document.getElementById("phone")||document.querySelector('input[name="customer_phone"]')||document.querySelector('input[name="phone"]');const discountInput=document.querySelector('input[name="discount_code"]');if(!phoneInput||!discountInput)return false;if(phoneInput.__prPhoneCouponRevalidate)return true;phoneInput.__prPhoneCouponRevalidate=true;function currentValue(){return window.PhoneInput&&window.PhoneInput.full(phoneInput)||(phoneInput.value||"").trim()}let lastSeenPhone=currentValue();let timer=null;function maybeRevalidate(){const currentPhone=currentValue();if(currentPhone===lastSeenPhone)return;lastSeenPhone=currentPhone;const code=(discountInput.value||"").trim();if(code.length<3)return;discountInput.dispatchEvent(new Event("blur"))}phoneInput.addEventListener("input",function(){if(timer)clearTimeout(timer);timer=setTimeout(maybeRevalidate,500)});phoneInput.addEventListener("change",maybeRevalidate);phoneInput.addEventListener("blur",maybeRevalidate);return true}function tryInit(attempts){if(init())return;if(attempts<=0)return;setTimeout(function(){tryInit(attempts-1)},200)}if(document.readyState==="loading"){document.addEventListener("DOMContentLoaded",function(){tryInit(15)})}else{tryInit(15)}})();